$ cat GracefulShutdown.java | grep -A8 'shutdown'
void shutdown(Duration grace) throws InterruptedException {
    running = false;
    thread.interrupt();
    thread.join(grace.toMillis());
    if (thread.isAlive()) {
        log.warn("{}ms 안에 안 끝났다. 강제 종료는 없다", grace.toMillis());
        metrics.counter("worker.forced").increment();
    }
}

